  const col = document.createElement('canvas'); col.width = W; col.height = H; const c = col.getContext('2d');
  const img = c.createImageData(W, H), d = img.data;
  const rgb = h => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
  const L1 = rgb(C.land), L2 = rgb(C.land2), FO = rgb(C.forest), DS = rgb(C.desert), IC = rgb(C.ice), BE = rgb(C.beach), BO = rgb(C.boreal), TU = rgb(C.tundra);
